-- Column masks for Restricted attributes (A3: Security and Compliance approval required)
CREATE FUNCTION IF NOT EXISTS main.ACME_CUSTOMER_CURATED.mask_restricted(v STRING) RETURNS STRING RETURN CASE WHEN is_account_group_member('restricted_readers') THEN v ELSE '***' END;
-- ALTER TABLE main.ACME_CUSTOMER_CURATED.DIM_CUSTOMER_ACCOUNT ALTER COLUMN CUSTOMER_NAME SET MASK main.ACME_CUSTOMER_CURATED.mask_restricted;
